function t(n){if(n==null||n==="")return"—";const i=Number(n);return Number.isFinite(i)?new Intl.NumberFormat("es-BO",{minimumFractionDigits:2,maximumFractionDigits:2}).format(i):"—"}function r(n){if(n==null||n==="")return"—";const i=Number(n);return Number.isFinite(i)?new Intl.NumberFormat("es-BO",{minimumFractionDigits:0,maximumFractionDigits:2}).format(i):"—"}export{r as a,t as f};
